const items = $('Telegram Trigger').all();

for (const item of items) {

  // پیدا کردن پیام
  const msg =
    item.json.callback_query?.message ||
    item.json.message ||
    item.json.channel_post ||
    item.json;

  let fileId = null;
  let mediaType = "text";

  // تشخیص نوع فایل
  if (msg.photo?.length) {
    fileId = msg.photo[msg.photo.length - 1].file_id;
    mediaType = "photo";

  } else if (msg.video) {
    fileId = msg.video.file_id;
    mediaType = "video";

  } else if (msg.audio) {
    fileId = msg.audio.file_id;
    mediaType = "audio";

  } else if (msg.voice) {
    fileId = msg.voice.file_id;
    mediaType = "voice";

  } else if (msg.document) {
    fileId = msg.document.file_id;
    mediaType = "document";

  } else if (msg.animation) {
    fileId = msg.animation.file_id;
    mediaType = "animation";
  }

  // متن یا کپشن
  const textContent = msg.caption || msg.text || "";

  item.json.my_data = {
    has_media: fileId !== null,
    media_type: mediaType,
    file_id: fileId,
    media_group_id: msg.media_group_id || null,
    text_content: textContent,
    is_album_part_without_text: !!(msg.media_group_id && !textContent),

    // اطلاعات callback
    callback_data: item.json.callback_query?.data || null,
    callback_id: item.json.callback_query?.id || null,
    clicked_by: item.json.callback_query?.from?.id || null,
    message_id: msg.message_id,
    chat_id: msg.chat?.id || null
  };
}

return items;

