let approvedText = botText
  .replace("🖼 **آلبوم دریافت شد.**\n\n📝 متن پیشنهادی هوش مصنوعی برای کپشن:\n\n", "")
  .replace("🖼 **آلبوم بدون کپشن دریافت شد.**\nجهت ارسال مستقیم به کانال تایید کنید.", "");

// ۲. استخراج ردیف‌های دیتابیس (که ورودی مستقیم این نود هستند)
let albumRows = [];
if (mediaGroupId) {
   albumRows = $input.all().map(item => item.json);
}

if (mediaGroupId && albumRows.length > 0) {
  // مرتب‌سازی عکس‌ها بر اساس ترتیب ارسالشان به ربات
  albumRows.sort((a, b) => a.message_id - b.message_id);

  let mediaArray = albumRows.map(row => ({
    type: row.media_type,
    media: row.file_id
  }));

  if (approvedText.trim() !== "") {
    mediaArray[0].caption = approvedText;
  }

  endpoint = "sendMediaGroup";
  payload = {
    chat_id: targetChannel,
    media: mediaArray
  };
} else if (originalMsg.photo || originalMsg.video || originalMsg.document || originalMsg.voice || originalMsg.audio) {
  payload.caption = approvedText;
} else {
  endpoint = "sendMessage";
  payload = {
    chat_id: targetChannel,
    text: approvedText
  };
}

